import itertools, json

riders = ["R", "S", "T", "Y"]
bikes = ["F", "G", "H", "J"]

def valid(d1, d2):
    for r in riders:
        if d1[r] == d2[r]:
            return False
    if "F" in (d1["R"], d2["R"]):
        return False
    if "J" in (d1["Y"], d2["Y"]):
        return False
    if "H" not in (d1["T"], d2["T"]):
        return False
    if d2["S"] != d1["Y"]:
        return False
    return True

sols = []
for p1 in itertools.permutations(bikes):
    d1 = dict(zip(riders, p1))
    if d1["T"] != "J":
        continue
    for p2 in itertools.permutations(bikes):
        d2 = dict(zip(riders, p2))
        if valid(d1, d2):
            sols.append((d1, d2))

options = {
    "A": lambda d1, d2: d2["R"] == "G",
    "B": lambda d1, d2: d1["S"] == "H",
    "C": lambda d1, d2: d2["Y"] == "H",
    "D": lambda d1, d2: "J" in (d1["S"], d2["S"]),
    "E": lambda d1, d2: "G" in (d1["T"], d2["T"]),
}

possible = [k for k, f in options.items() if any(f(a, b) for a, b in sols)]
counts = {k: sum(1 for a, b in sols if f(a, b)) for k, f in options.items()}

if len(possible) == 1:
    ans = possible[0]
else:
    ans = "UNSUPPORTED"

print(json.dumps({
    "final_answer": ans,
    "evidence": {"num_solutions": len(sols), "option_counts": counts, "possible": possible}
}))
